import { useGLTF, useAnimations } from '@react-three/drei'
import { useEffect } from 'react'

export function IzakayaFrontBayIzakayaAlleyAndRamenShop(props) {
  const { scene, animations } = useGLTF('https://cdn.3dassets.dev/assets/36441/v1/model.glb')
  const { actions, names } = useAnimations(animations, scene)
  useEffect(() => {
    const action = actions[names[0]]
    action?.reset().play()
    return () => { action?.stop() }
  }, [actions, names])
  return <primitive object={scene} {...props} />
}
